export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Quote {
  premium: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

export class UnknownItemTypeError extends Error {
  constructor(type: string) {
    super(`unknown item type: ${type}`);
  }
}

function basePremium(item: Item): number {
  const base = BASE_PREMIUMS[item.type];
  if (base === undefined) throw new UnknownItemTypeError(item.type);
  return base;
}

export function quote(_customer: Customer, items: Item[], _priorContracts: number): Quote {
  const policyBase = items.reduce((sum, item) => sum + basePremium(item), 0);
  const total = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
  return { premium: Math.ceil(total) };
}
EOF
